<script>
(function () {
  var base = document.documentElement.getAttribute('data-base') || '';
  var el = document.getElementById('ab-imap');
  if (el && window.L) {
    var ll = [parseFloat(el.getAttribute('data-lat')), parseFloat(el.getAttribute('data-lng'))];
    var m = L.map(el, { scrollWheelZoom: false, zoomControl: false, attributionControl: true }).setView(ll, 15);
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', { maxZoom: 19, attribution: '&copy; OpenStreetMap' }).addTo(m);
    L.marker(ll, { icon: L.divIcon({ className: 'ab-pin', html: '<span></span>', iconSize: [34, 34], iconAnchor: [17, 34] }) }).addTo(m);
  }
  [].forEach.call(document.querySelectorAll('.ab-copy'), function (b) {
    b.addEventListener('click', function () {
      var t = b.getAttribute('data-copy'), lab = b.querySelector('span');
      var done = function () { lab.textContent = 'Copiado!'; setTimeout(function () { lab.textContent = 'Copiar'; }, 2000); };
      if (navigator.clipboard) navigator.clipboard.writeText(t).then(done, done); else done();
    });
  });
  [].forEach.call(document.querySelectorAll('.ab-share'), function (b) {
    b.addEventListener('click', function () {
      var u = b.getAttribute('data-url'), t = b.getAttribute('data-title');
      if (navigator.share) navigator.share({ title: t, url: u }).catch(function () {});
      else window.open('https://wa.me/?text=' + encodeURIComponent(t + ' ' + u), '_blank', 'noopener');
    });
  });
  [].forEach.call(document.querySelectorAll('[data-ab-wa]'), function (a) {
    a.addEventListener('click', function () { try { navigator.sendBeacon(base + '/api/amigos-clique.php', new Blob(['slug=' + encodeURIComponent(a.getAttribute('data-ab-wa'))], { type: 'application/x-www-form-urlencoded' })); } catch (e) {} });
  });
})();
</script>

